{"file_path": "main.ts", "content": "// A token-radar-01 entry (Node 22, standard library only).
//
// The program reads the sealed snapshot from /input/snapshot.json (or --input <file|dir>), scores
// every launch candidate with the model in lib/model.ts, writes the ranked board to
// /output/board.json, writes the dashboard's data to /output/data.js, copies this repository's
// dashboard/ and screenshots/ into /output, and writes /output/dossier.json last with the vendored
// make.fun library, byte for byte the summary the judge reads.
//
// The dashboard is a static page, no framework and no network: dashboard/index.html, app.css and
// app.js render /output/data.js, which this program writes from the same board it hands in, so the
// page and the board cannot disagree.
//
// Outside the grader's container, MAKEFUN_OUTPUT_DIR stands in for /output:
//   mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts --input ../input/snapshot.json

import { copyFileSync, existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { boardIssue, buildRadar, dataScript, parseSnapshot } from './lib/model.ts';
import { buildDossier } from './vendor/makefun-board.ts';

const here = fileURLToPath(new URL('.', import.meta.url));

/** The scorer's caps, as the rules state them: the dossier's text cap shapes the bytes, the rest refuse. */
const TEXT_MAX_BYTES = 65_536;
const SCREENSHOT_CAPS = { max: 4, max_bytes: 524_288 };
const DASHBOARD_CAPS = { max_files: 400, max_bytes: 4_194_304 };
const IMAGE_NAME = /^[A-Za-z0-9_][A-Za-z0-9._-]{0,127}$/;

/** --name <value> out of the arguments, or the fallback. */
function arg(name: string, fallback: string): string {
  const at = process.argv.indexOf(`--${name}`);
  if (at >= 0 && at + 1 < process.argv.length) return process.argv[at + 1]!;
  const withEquals = process.argv.find((a) => a.startsWith(`--${name}=`));
  return withEquals === undefined ? fallback : withEquals.slice(name.length + 3);
}

const inputArg = arg('input', '/input');
const inputFile = inputArg.endsWith('.json') ? inputArg : join(inputArg, 'snapshot.json');
if (!existsSync(inputFile)) {
  process.stderr.write(`token radar: no snapshot at ${inputFile}: pass --input <snapshot.json|directory> or mount the sealed /input\n`);
  process.exit(2);
}
const out = arg('output', process.env.MAKEFUN_OUTPUT_DIR ?? '/output');

const snapshot = parseSnapshot(readFileSync(inputFile, 'utf8'));
const { board, radar } = buildRadar(snapshot);
const issue = boardIssue(board, snapshot);
if (issue !== null) {
  process.stderr.write(`token radar: the model wrote a board the gate refuses: ${issue}\n`);
  process.exit(1);
}

mkdirSync(out, { recursive: true });
writeFileSync(join(out, 'board.json'), `${JSON.stringify({ rows: board })}\n`);
writeFileSync(join(out, 'data.js'), dataScript(radar));

/** Copy one directory's regular files into `to`, skipping names that start with a dot. */
function copyFiles(from: string, to: string): string[] {
  if (!existsSync(from)) return [];
  mkdirSync(to, { recursive: true });
  const copied: string[] = [];
  for (const name of readdirSync(from)) {
    if (name.startsWith('.')) continue;
    const path = join(from, name);
    if (!statSync(path).isFile()) continue;
    copyFileSync(path, join(to, name));
    copied.push(name);
  }
  return copied;
}

copyFiles(join(here, 'dashboard'), join(out, 'dashboard'));
const shots = copyFiles(join(here, 'screenshots'), join(out, 'screenshots'));
if (shots.length < 3) {
  process.stderr.write(`token radar: screenshots/ holds ${shots.length} image${shots.length === 1 ? '' : 's'}: hand in 3, the board, a detail view and a filtered view\n`);
  process.exit(1);
}
for (const name of shots) {
  if (!IMAGE_NAME.test(name)) {
    process.stderr.write(`token radar: screenshots/${name}: a name is letters, digits and . _ -, 1 to 128 characters\n`);
    process.exit(1);
  }
}

// The dossier is written last: the scorer rebuilds it from this /output and compares bytes.
writeFileSync(join(out, 'dossier.json'), buildDossier(out, { text_max_bytes: TEXT_MAX_BYTES, screenshots: SCREENSHOT_CAPS, dashboard: DASHBOARD_CAPS }));

process.stdout.write(
  `token radar: ${snapshot.protocols.length} protocols, ${snapshot.watchlist.length} on the watchlist, ${board.length} rows scored (${radar.early_size} early, ${radar.live_size} live set aside)\n` +
    `token radar: wrote board.json, data.js, dashboard/ and screenshots/ (${shots.length} images) and dossier.json under ${out}\n`,
);
"}

{"file_path": "lib/model.ts", "content": "// The token radar's model: one sealed snapshot of the protocol universe in, one ranked board out.
//
// The board covers every slug in the snapshot's watchlist (the floor, never a ceiling) and adds the
// pre-token protocols below the floor that pass the same product tests the house's watchlist rule
// states: no token recorded, not an exchange, not a versioned pool of another protocol, and not a
// wrapped, staked or exchange-issued product of a token that already trades. Those early rows are
// the ones a radar exists to find: big enough to matter, early enough to farm before any launch.
//
// Implied value follows only from the snapshot's own figures, one stated formula for every row:
//
//   implied = tvl_usd x category_multiple x growth_multiplier x maturity_multiplier
//
//   category_multiple  what a dollar of TVL in this category has historically been worth in token
//                      value: fee-capturing trading and lending at the top, pass-through wrappers
//                      and bridges at the bottom. One table, stated in the dashboard, applied to all.
//   growth_multiplier  1 + clamp(change_7d, -50, 100) / 100 x 0.6: a protocol whose TVL grew 100%
//                      in a week is worth 1.6x its base; one that halved is worth 0.7x.
//   maturity_multiplier  0.55 + 0.45 x min(age_days, 1460) / 1460: the longer a protocol has run
//                      with no token, the more of its record a launch can be priced on. A protocol
//                      whose listing day DefiLlama does not report is scored as 365 days old.
//
// No protocol name is ever special-cased: the same function scores every row, and the dashboard
// shows each row's three multipliers so a reader can check the arithmetic.

/** The snapshot's protocol entry: exactly the ten fields the sealed input carries. */
export interface SnapshotProtocol {
  slug: string;
  name: string;
  category: string | null;
  chains: string[];
  tvl_usd: number;
  change_7d: number | null;
  mcap_usd: number | null;
  listed_at: string | null;
  gecko_id: string | null;
  symbol: string | null;
}

/** The whole snapshot document. */
export interface Snapshot {
  as_of: string;
  source: string;
  floor_usd: number;
  protocols: SnapshotProtocol[];
  watchlist: string[];
}

/** The model's constants, as the dashboard states them. */
export interface ModelConstants {
  category_multiples: Record<string, number>;
  default_multiple: number;
  growth_weight: number;
  growth_floor: number;
  growth_cap: number;
  maturity_floor: number;
  maturity_range: number;
  maturity_days: number;
  unknown_age_days: number;
}

export const MODEL: ModelConstants = {
  category_multiples: {
    Dexs: 0.35,
    Lending: 0.32,
    CDP: 0.3,
    Derivatives: 0.3,
    Chain: 0.28,
    'Yield Aggregator': 0.26,
    Yield: 0.24,
    'Onchain Capital Allocator': 0.24,
    'Risk Curators': 0.22,
    RWA: 0.22,
    'Basis Trading': 0.2,
    'Staking Pool': 0.2,
    'Liquid Staking': 0.18,
    Bridge: 0.16,
    'Canonical Bridge': 0.14,
  },
  default_multiple: 0.22,
  growth_weight: 0.6,
  growth_floor: -50,
  growth_cap: 100,
  maturity_floor: 0.55,
  maturity_range: 0.45,
  maturity_days: 1460,
  unknown_age_days: 365,
};

/** The model's version label: the dashboard names it. */
export const MODEL_VERSION = 'radar-2';

/** How many live-token protocols the dashboard's Live view carries, by market cap. */
export const LIVE_ROWS = 30;

/** One row of board.json: the ranked board's row. */
export interface BoardRow {
  rank: number;
  slug: string;
  name: string;
  category: string | null;
  chains: string[];
  tvl_usd: number;
  change_7d: number | null;
  mcap_usd: number | null;
  listed_at: string | null;
  gecko_id: string | null;
  symbol: string | null;
  token_status: 'pre-token';
  on_watchlist: boolean;
  age_days: number | null;
  implied_value_usd: number;
  model: {
    category_multiple: number;
    growth_pct: number;
    growth_multiplier: number;
    maturity_multiplier: number;
    age_days: number | null;
  };
  farm_capital_usd: number;
  farm_steps: string[];
}

/** The dashboard's view of one row: the board row as the page renders it. */
export interface RadarRow extends BoardRow {}

/** A live-token protocol: it already trades, so the page shows the market's own value, not a model's. */
export interface LiveRow {
  slug: string;
  name: string;
  category: string | null;
  chains: string[];
  tvl_usd: number;
  mcap_usd: number | null;
  change_7d: number | null;
  symbol: string | null;
}

/** Everything the dashboard needs: the board, the live set, and the model it runs. */
export interface RadarData {
  as_of: string;
  source: string;
  floor_usd: number;
  model: ModelConstants;
  model_version: string;
  protocols_size: number;
  watchlist_size: number;
  board_size: number;
  early_size: number;
  live_size: number;
  rows: RadarRow[];
  live: LiveRow[];
}

/** Why the snapshot is not one this model can score. */
export class SnapshotError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SnapshotError';
  }
}

const DAY_MS = 86_400_000;

/** A finite number, else `fallback`. */
function finite(value: unknown, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
}

/** A whole day count from `from` to `to`, clamped at zero; null when either date is absent or bad. */
export function ageDays(asOf: string, listedAt: string | null): number | null {
  if (listedAt === null) return null;
  const a = Date.parse(`${asOf}T00:00:00Z`);
  const b = Date.parse(`${listedAt}T00:00:00Z`);
  if (!Number.isFinite(a) || !Number.isFinite(b)) return null;
  return Math.max(0, Math.floor((a - b) / DAY_MS));
}

const round4 = (n: number): number => Math.round(n * 1e4) / 1e4;

/** The category's value multiple under `model`: the table first, the default after. */
export function categoryMultiple(p: SnapshotProtocol, model: ModelConstants): number {
  if (p.category !== null && Object.prototype.hasOwnProperty.call(model.category_multiples, p.category)) {
    return model.category_multiples[p.category]!;
  }
  return model.default_multiple;
}

/** The multipliers and the implied value one protocol gets under `model`. */
export function impliedValue(
  protocol: SnapshotProtocol,
  asOf: string,
  model: ModelConstants,
): { implied: number; multiple: number; growthPct: number; growthMult: number; maturityMult: number; age: number | null } {
  const age = ageDays(asOf, protocol.listed_at);
  const multiple = categoryMultiple(protocol, model);
  const rawGrowth = finite(protocol.change_7d, 0);
  const growthPct = Math.min(model.growth_cap, Math.max(model.growth_floor, rawGrowth));
  const growthMult = 1 + (growthPct / 100) * model.growth_weight;
  const ageForModel = age ?? model.unknown_age_days;
  const maturityMult =
    model.maturity_floor + (Math.min(Math.max(ageForModel, 0), model.maturity_days) / model.maturity_days) * model.maturity_range;
  const implied = Math.max(1, Math.round(protocol.tvl_usd * multiple * growthMult * maturityMult));
  return { implied, multiple, growthPct, growthMult, maturityMult, age };
}

/** DefiLlama's version-marker rule: a name ending in a release is a pool of another protocol. */
const VERSIONED = /\s(V\d+(\.\d+)?|v\d+(\.\d+)?|\d+\.\d+)$/;

/** A whole word that marks a wrapped or staked product of a token that already trades. */
const PRODUCT_WORD = /\b(wrapped|staked|staking)\b/i;

/** An exchange's name at the head of a name: its staked or bridged product, not a launch of its own. */
const EXCHANGE_HEAD = /^(Binance|Coinbase|Bybit|Kraken|Bitget|OKX|Bitfinex|Gemini)\b/;

/** Whether a protocol records no token at all. */
export function isPreToken(p: SnapshotProtocol): boolean {
  return p.mcap_usd === null && p.gecko_id === null && p.symbol === null;
}

/**
 * Whether a pre-token protocol is a launch candidate of its own: not an exchange, not a versioned
 * pool, and not a wrapped, staked or exchange-issued product of a token that already trades. These
 * are the name and category tests of the house's watchlist rule, applied below the floor as well.
 */
export function isLaunchCandidate(p: SnapshotProtocol): boolean {
  return (
    isPreToken(p) &&
    p.category !== 'CEX' &&
    !VERSIONED.test(p.name) &&
    !PRODUCT_WORD.test(p.name) &&
    !EXCHANGE_HEAD.test(p.name)
  );
}

/** The snapshot's protocol by slug. */
function bySlug(protocols: SnapshotProtocol[]): Map<string, SnapshotProtocol> {
  return new Map(protocols.map((p) => [p.slug, p]));
}

/** The protocols the board ranks, strongest first, with ranks 1..n. */
export function buildBoard(snapshot: Snapshot, model: ModelConstants = MODEL): BoardRow[] {
  const index = bySlug(snapshot.protocols);
  const watchlist = new Set(snapshot.watchlist);
  const chosen = new Map<string, SnapshotProtocol>();
  // The watchlist is the floor: every slug on it is ranked, whatever its record looks like.
  for (const slug of snapshot.watchlist) {
    const p = index.get(slug);
    if (p !== undefined) chosen.set(slug, p);
  }
  // The early radar: every launch candidate below the floor, not a capped sample. A board that
  // carries all of them cannot miss the one that launches next.
  for (const p of snapshot.protocols) {
    if (!chosen.has(p.slug) && isLaunchCandidate(p) && p.tvl_usd < snapshot.floor_usd) chosen.set(p.slug, p);
  }

  const scored = [...chosen.values()].map((p) => ({ p, ...impliedValue(p, snapshot.as_of, model) }));
  scored.sort((a, b) => b.implied - a.implied || (a.p.slug < b.p.slug ? -1 : a.p.slug > b.p.slug ? 1 : 0));
  return scored.map((s, i) => ({
    rank: i + 1,
    slug: s.p.slug,
    name: s.p.name,
    category: s.p.category,
    chains: s.p.chains,
    tvl_usd: s.p.tvl_usd,
    change_7d: s.p.change_7d,
    mcap_usd: s.p.mcap_usd,
    listed_at: s.p.listed_at,
    gecko_id: s.p.gecko_id,
    symbol: s.p.symbol,
    token_status: 'pre-token' as const,
    on_watchlist: watchlist.has(s.p.slug),
    age_days: s.age,
    implied_value_usd: s.implied,
    model: {
      category_multiple: s.multiple,
      growth_pct: s.growthPct,
      growth_multiplier: round4(s.growthMult),
      maturity_multiplier: round4(s.maturityMult),
      age_days: s.age,
    },
    farm_capital_usd: capitalFor(s.p),
    farm_steps: farmSteps(s.p, s.age),
  }));
}

/** The first chain a protocol names, or a neutral phrase. */
function chainOf(p: SnapshotProtocol): string {
  return p.chains.length > 0 ? p.chains[0]! : 'its main chain';
}

/** How much capital one farm position needs, from the protocol's own TVL. */
export function capitalFor(p: SnapshotProtocol): number {
  if (p.tvl_usd >= 1_000_000_000) return 250;
  if (p.tvl_usd >= 100_000_000) return 150;
  if (p.tvl_usd >= 25_000_000) return 100;
  return 50;
}

/** How long to hold, from the protocol's age: younger protocols get a longer qualifying window. */
function holdDaysFor(age: number | null): number {
  if (age === null) return 45;
  if (age < 180) return 60;
  if (age < 365) return 45;
  return 30;
}

/** A step as one string: its action, then its cost and time, within the gate's 20..600 characters. */
function step(text: string, cost: string, time: string): string {
  const s = `${text} Cost: ${cost}. Time: ${time}.`;
  return s.length > 600 ? `${s.slice(0, 596)}...` : s;
}

/** The core farming action for a category, in the words a farmer can follow. */
function coreAction(p: SnapshotProtocol, capital: number, chain: string): string {
  const c = (p.category ?? '').toLowerCase();
  const n = p.name;
  if (c.includes('lend')) return `Supply $${capital} of USDC to ${n} on ${chain}, then borrow $${Math.round(capital / 2)} of USDC against it and supply that back once, so both sides of the market see the wallet.`;
  if (c.includes('cdp')) return `Deposit $${capital} of collateral into a ${n} vault on ${chain} and mint $${Math.round(capital / 2)} of its stablecoin, keeping the collateral ratio above 200%.`;
  if (c.includes('dex')) return `Swap $${capital} of USDC for the pool's other asset on ${n} and add both sides as liquidity to its main ${chain} pool.`;
  if (c.includes('derivative') || c.includes('perpetual')) return `Deposit $${capital} of USDC as margin on ${n} and open one small hedged position, long and short the same size, so the volume is real and the risk is flat.`;
  if (c.includes('bridge') || c.includes('canonical')) return `Bridge $${capital} of USDC from Ethereum to ${chain} through ${n}, then bridge a smaller amount back a week later so both directions count.`;
  if (c.includes('staking') || c.includes('restak')) return `Stake $${capital} of the chain's staking asset through ${n} on ${chain} and keep the liquid receipt token in the same wallet.`;
  if (c.includes('curator') || c.includes('allocator') || c.includes('yield')) return `Deposit $${capital} of USDC into a ${n} vault on ${chain} and leave the shares untouched, so the deposit ages in the vault's records.`;
  if (c.includes('rwa')) return `Mint $${capital} of ${n}'s yield asset on ${chain} with USDC and hold it; make one small redemption later so both flows are recorded.`;
  if (c.includes('basis')) return `Open the basis position ${n} runs with $${capital} of USDC on ${chain}: long the spot asset, short the same size on its perpetual market.`;
  if (c.includes('chain')) return `Move $${capital} of USDC onto ${n} and use three of its native apps in the first week, so the wallet is a real user of the chain.`;
  if (c.includes('prediction')) return `Fund $${capital} and take one position on each side of a liquid market on ${n}, so the wallet trades without betting the farm on one outcome.`;
  if (c.includes('insurance')) return `Buy $${capital} of cover from ${n} on ${chain} for the longest term it offers and keep the policy NFT in the wallet.`;
  return `Deposit $${capital} of USDC into ${n} on ${chain} through its own app and keep the position open.`;
}

/** The second, deepening action for a category: the step that separates a farmer from a passer-by. */
function deepenAction(p: SnapshotProtocol, chain: string): string {
  const c = (p.category ?? '').toLowerCase();
  const n = p.name;
  if (c.includes('lend')) return `Vote in one ${n} governance poll or delegate to an active delegate, so the wallet appears in the protocol's governance record as well as its market.`;
  if (c.includes('dex')) return `Make two more swaps a week on ${n} at different hours, so the wallet's volume looks like use and not a single scripted pass.`;
  if (c.includes('bridge') || c.includes('canonical')) return `Use the bridged funds in one ${chain} app the same week, so the bridge record ends in real activity and not a round trip.`;
  if (c.includes('derivative') || c.includes('perpetual')) return `Deposit a second, smaller amount into ${n}'s liquidity vault, so the wallet is both a trader and a backer of the venue.`;
  if (c.includes('staking') || c.includes('restak')) return `Delegate or vote once with the staked position if ${n} offers it, so the wallet is counted as a participant and not only a balance.`;
  if (c.includes('chain')) return `Claim one faucet or ecosystem quest on ${n} each week and keep a small native-token balance for gas, so the wallet never looks rented.`;
  return `Repeat the core action once more in the second month at half size, so the wallet's history spans more than one snapshot of the protocol.`;
}

/**
 * A protocol's farm plan: seven steps, each an action with a cost and a time. The plan is derived
 * from the protocol's own record (category, chains, TVL, age), never from a hand-written list.
 */
export function farmSteps(p: SnapshotProtocol, age: number | null): string[] {
  const chain = chainOf(p);
  const capital = capitalFor(p);
  const hold = holdDaysFor(age);
  const gas = capital >= 150 ? 8 : 4;
  return [
    step(
      `Start a fresh wallet for this farm and fund it on ${chain}; keep its seed phrase offline and never mix it with a wallet that holds real savings.`,
      'under $3 of gas for the funding transaction',
      '5 minutes',
    ),
    step(
      coreAction(p, capital, chain),
      `$${capital} of capital and about $${gas} of gas`,
      '15 minutes to set up',
    ),
    step(
      deepenAction(p, chain),
      'about $2 of gas each time',
      '10 minutes a week',
    ),
    step(
      `Hold the position for at least ${hold} days, checking it once a week, so the activity is counted in more than one weekly snapshot of ${p.name}.`,
      `the $${capital} stays in the position`,
      `${hold} days`,
    ),
    step(
      `Open ${p.name}'s own points, rewards or governance page once a month and note what it counts; claim only from a link that page publishes, and never pay anyone to claim for you.`,
      'nothing to check, and never a fee to claim',
      '10 minutes a month',
    ),
    step(
      `Keep the whole position under a tenth of your farm budget: ${p.name} records no token today, a launch is a possibility this plan prices, never a promise it relies on.`,
      `at most $${capital} at risk in one protocol`,
      '2 minutes to size',
    ),
    step(
      `Log the wallet, the dates and every transaction hash in a farm log, and unwind in two halves a week apart once the hold ends or a token is announced.`,
      'nothing but the log, and normal gas to exit',
      '5 minutes, then 10 minutes to unwind',
    ),
  ];
}

/** The live-token protocols, by market cap, for the dashboard's Live view. */
export function liveRows(snapshot: Snapshot): LiveRow[] {
  return snapshot.protocols
    .filter((p) => !isPreToken(p) && p.category !== 'CEX')
    .sort((a, b) => (b.mcap_usd ?? 0) - (a.mcap_usd ?? 0) || b.tvl_usd - a.tvl_usd || (a.slug < b.slug ? -1 : 1))
    .slice(0, LIVE_ROWS)
    .map((p) => ({
      slug: p.slug,
      name: p.name,
      category: p.category,
      chains: p.chains,
      tvl_usd: p.tvl_usd,
      mcap_usd: p.mcap_usd,
      change_7d: p.change_7d,
      symbol: p.symbol,
    }));
}

/** Everything the dashboard renders, from the snapshot. */
export function buildRadar(snapshot: Snapshot, model: ModelConstants = MODEL): { board: BoardRow[]; radar: RadarData } {
  const board = buildBoard(snapshot, model);
  const live = liveRows(snapshot);
  const early = board.filter((r) => !r.on_watchlist).length;
  const radar: RadarData = {
    as_of: snapshot.as_of,
    source: snapshot.source,
    floor_usd: snapshot.floor_usd,
    model,
    model_version: MODEL_VERSION,
    protocols_size: snapshot.protocols.length,
    watchlist_size: snapshot.watchlist.length,
    board_size: board.length,
    early_size: early,
    live_size: live.length,
    rows: board,
    live,
  };
  return { board, radar };
}

/** The snapshot out of a file's text, refused unless it is the shape the model scores. */
export function parseSnapshot(text: string): Snapshot {
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    throw new SnapshotError('snapshot.json is not JSON');
  }
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) throw new SnapshotError('snapshot.json is not a JSON object');
  const o = raw as Record<string, unknown>;
  if (typeof o.as_of !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(o.as_of)) throw new SnapshotError('snapshot.json has no as_of date');
  if (typeof o.source !== 'string') throw new SnapshotError('snapshot.json has no source');
  if (typeof o.floor_usd !== 'number' || !Number.isSafeInteger(o.floor_usd) || o.floor_usd <= 0) throw new SnapshotError('snapshot.json has no floor_usd');
  if (!Array.isArray(o.protocols)) throw new SnapshotError('snapshot.json has no protocols array');
  if (!Array.isArray(o.watchlist) || o.watchlist.some((s) => typeof s !== 'string')) throw new SnapshotError('snapshot.json has no watchlist of slugs');
  const protocols = o.protocols.map((v, i) => {
    if (typeof v !== 'object' || v === null || Array.isArray(v)) throw new SnapshotError(`snapshot.json's protocol ${i} is not an object`);
    const p = v as Record<string, unknown>;
    if (typeof p.slug !== 'string' || typeof p.name !== 'string' || typeof p.tvl_usd !== 'number' || !Number.isFinite(p.tvl_usd)) {
      throw new SnapshotError(`snapshot.json's protocol ${i} lacks a slug, a name or a TVL`);
    }
    return {
      slug: p.slug,
      name: p.name,
      category: typeof p.category === 'string' ? p.category : null,
      chains: Array.isArray(p.chains) ? p.chains.filter((c): c is string => typeof c === 'string') : [],
      tvl_usd: p.tvl_usd,
      change_7d: typeof p.change_7d === 'number' && Number.isFinite(p.change_7d) ? p.change_7d : null,
      mcap_usd: typeof p.mcap_usd === 'number' && Number.isFinite(p.mcap_usd) ? p.mcap_usd : null,
      listed_at: typeof p.listed_at === 'string' ? p.listed_at : null,
      gecko_id: typeof p.gecko_id === 'string' ? p.gecko_id : null,
      symbol: typeof p.symbol === 'string' ? p.symbol : null,
    };
  });
  return {
    as_of: o.as_of,
    source: o.source,
    floor_usd: o.floor_usd,
    protocols,
    watchlist: o.watchlist as string[],
  };
}

/** Why a board is not one the gate will take, or null: coverage, ranks, order, shared values, farm steps. */
export function boardIssue(board: BoardRow[], snapshot: Snapshot): string | null {
  if (board.length < 100 || board.length > 4000) return `the board holds ${board.length} rows, outside 100..4000`;
  const slugs = new Set(board.map((r) => r.slug));
  if (slugs.size !== board.length) return 'the board names a slug twice';
  const known = new Set(snapshot.protocols.map((p) => p.slug));
  for (const r of board) if (!known.has(r.slug)) return `${r.slug} is not one of the snapshot's protocols`;
  const missing = snapshot.watchlist.filter((s) => !slugs.has(s));
  if (missing.length > 0) return `the board misses ${missing.length} watchlist slug${missing.length === 1 ? '' : 's'}: ${missing.slice(0, 5).join(', ')}`;
  const ranks = board.map((r) => r.rank).sort((a, b) => a - b);
  for (let i = 0; i < ranks.length; i++) if (ranks[i] !== i + 1) return `rank ${i + 1} is ${ranks[i]}`;
  const byRank = [...board].sort((a, b) => a.rank - b.rank);
  for (let i = 1; i < byRank.length; i++) {
    if (byRank[i]!.implied_value_usd > byRank[i - 1]!.implied_value_usd) return `rank ${byRank[i]!.rank} outranks rank ${byRank[i - 1]!.rank} on implied value`;
  }
  if (board.length >= 2 && byRank[0]!.implied_value_usd === byRank[byRank.length - 1]!.implied_value_usd) {
    return `all ${board.length} rows share the same implied value: a board that ranks nothing by value is not a ranking`;
  }
  for (const r of board) {
    if (!Number.isSafeInteger(r.implied_value_usd) || r.implied_value_usd <= 0 || r.implied_value_usd > 100_000_000_000_000) {
      return `${r.slug} has implied value ${r.implied_value_usd}`;
    }
    if (r.farm_steps.length < 3 || r.farm_steps.length > 12) return `${r.slug} has ${r.farm_steps.length} farm steps`;
    for (const s of r.farm_steps) {
      const t = s.trim();
      if (t.length < 20 || t.length > 600) return `${r.slug} has a farm step of ${t.length} characters`;
    }
  }
  return null;
}

/** A compact data.js: the dashboard's whole dataset as one script, no fetch and no network. */
export function dataScript(radar: RadarData): string {
  return `window.RADAR=${JSON.stringify(radar)};\n`;
}
"}

{"file_path": "dashboard/app.css", "content": "/* Token Radar: a dark scope theme. Deep navy field, phosphor-green signal, amber for the watchlist.
   One column system, tabular numbers, no framework. */
:root {
  --bg: #070d1a;
  --bg2: #0a1322;
  --panel: #0d1830;
  --panel2: #101f3d;
  --line: #1e2f4f;
  --line2: #2a4066;
  --ink: #eaf1fc;
  --muted: #90a6c6;
  --faint: #5f7699;
  --signal: #4ade80;
  --signal-dim: #1d4d33;
  --amber: #fbbf24;
  --red: #f87171;
  --cyan: #38bdf8;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace;
  --sans: "Avenir Next", Avenir, "Segoe UI", system-ui, -apple-system, sans-serif;
}
* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background:
    radial-gradient(1100px 480px at 85% -120px, rgba(56, 189, 248, 0.10), transparent 60%),
    radial-gradient(900px 500px at -10% 0, rgba(74, 222, 128, 0.07), transparent 55%),
    var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.45;
}
a { color: var(--cyan); text-decoration: none; }
a:hover { text-decoration: underline; }
.mono, td.n, .n { font-family: var(--mono); font-variant-numeric: tabular-nums; }

/* Masthead */
.mast { border-bottom: 1px solid var(--line); background: linear-gradient(180deg, rgba(16, 31, 61, 0.65), rgba(7, 13, 26, 0)); }
.mast-in { max-width: 1180px; margin: 0 auto; padding: 26px 20px 6px; display: flex; gap: 28px; align-items: flex-start; justify-content: space-between; flex-wrap: wrap; }
.brand { display: flex; gap: 16px; align-items: flex-start; min-width: 300px; }
.glyph { width: 46px; height: 46px; border: 1px solid var(--line2); border-radius: 50%; position: relative; flex: none; margin-top: 4px;
  background: radial-gradient(circle at 50% 50%, rgba(74, 222, 128, 0.16), transparent 62%); }
.glyph::before, .glyph::after { content: ""; position: absolute; border: 1px solid rgba(74, 222, 128, 0.35); border-radius: 50%; inset: 8px; }
.glyph::after { inset: 16px; }
.glyph span { position: absolute; width: 5px; height: 5px; border-radius: 50%; background: var(--signal); }
.glyph span:nth-child(1) { top: 9px; left: 20px; }
.glyph span:nth-child(2) { top: 24px; left: 30px; background: var(--amber); }
.glyph span:nth-child(3) { top: 29px; left: 11px; background: var(--cyan); }
h1 { font-size: 30px; line-height: 1.1; margin: 0 0 6px; letter-spacing: 0.2px; }
.tag { margin: 0; color: var(--muted); max-width: 560px; }
.stats { display: flex; gap: 10px; flex-wrap: wrap; }
.stat { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 8px 14px 9px; min-width: 104px; }
.stat b { display: block; font-family: var(--mono); font-size: 19px; font-weight: 600; color: var(--ink); }
.stat span { color: var(--faint); font-size: 11.5px; text-transform: uppercase; letter-spacing: 0.08em; }
.tabs { max-width: 1180px; margin: 0 auto; padding: 10px 20px 0; display: flex; gap: 4px; }
.tabs a { color: var(--muted); padding: 8px 14px; border: 1px solid transparent; border-bottom: none; border-radius: 9px 9px 0 0; font-weight: 600; }
.tabs a:hover { color: var(--ink); text-decoration: none; }
.tabs a.on { color: var(--signal); background: var(--bg2); border-color: var(--line); }

/* Layout */
main { max-width: 1180px; margin: 0 auto; padding: 20px; display: block; }
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; }
.lede { color: var(--muted); margin: 0 0 16px; max-width: 860px; }
.lede b { color: var(--ink); }

/* Controls */
.controls { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; padding: 12px; margin-bottom: 14px; }
.controls input[type="search"], .controls select {
  background: var(--bg2); color: var(--ink); border: 1px solid var(--line2); border-radius: 8px;
  padding: 8px 10px; font: inherit; font-size: 14px;
}
.controls input[type="search"] { min-width: 210px; flex: 1 1 210px; }
.controls label.check { display: inline-flex; gap: 7px; align-items: center; color: var(--muted); font-size: 14px; cursor: pointer; }
.controls .count { margin-left: auto; color: var(--faint); font-family: var(--mono); font-size: 13px; }
button.reset { background: none; border: 1px solid var(--line2); color: var(--muted); border-radius: 8px; padding: 8px 12px; font: inherit; font-size: 13.5px; cursor: pointer; }
button.reset:hover { color: var(--ink); border-color: var(--signal-dim); }

/* Table */
table { width: 100%; border-collapse: collapse; }
.board-wrap { overflow-x: auto; border-radius: 12px; }
thead th {
  text-align: left; font-size: 12px; text-transform: uppercase; letter-spacing: 0.07em; color: var(--faint);
  padding: 11px 12px; border-bottom: 1px solid var(--line); background: var(--panel2); white-space: nowrap;
}
thead th.sortable { cursor: pointer; }
thead th.sortable:hover { color: var(--ink); }
thead th .dir { color: var(--signal); }
tbody td { padding: 10px 12px; border-bottom: 1px solid rgba(30, 47, 79, 0.55); vertical-align: top; }
tbody tr { cursor: pointer; }
tbody tr:hover { background: rgba(56, 189, 248, 0.05); }
td.rank { font-family: var(--mono); color: var(--faint); width: 44px; }
td .pname { font-weight: 650; color: var(--ink); }
td .pcat { color: var(--faint); font-size: 12.5px; }
td.n { text-align: right; font-size: 14px; }
th.n { text-align: right; }
.pos { color: var(--signal); }
.neg { color: var(--red); }
.badge { display: inline-block; font-size: 11px; font-weight: 700; letter-spacing: 0.04em; padding: 1.5px 7px; border-radius: 999px; vertical-align: 2px; margin-left: 7px; }
.badge.watch { background: rgba(251, 191, 36, 0.14); color: var(--amber); border: 1px solid rgba(251, 191, 36, 0.4); }
.badge.early { background: rgba(74, 222, 128, 0.1); color: var(--signal); border: 1px solid rgba(74, 222, 128, 0.35); }
.chains { color: var(--muted); font-size: 13px; }
.bar { height: 5px; border-radius: 3px; background: var(--bg2); margin-top: 5px; min-width: 84px; }
.bar i { display: block; height: 100%; border-radius: 3px; background: linear-gradient(90deg, var(--signal-dim), var(--signal)); }
.empty { padding: 34px; text-align: center; color: var(--muted); }

/* Detail */
.back { display: inline-block; margin-bottom: 14px; font-weight: 600; }
.detail-head { display: flex; gap: 18px; flex-wrap: wrap; align-items: baseline; justify-content: space-between; }
.detail-head h2 { font-size: 26px; margin: 0; }
.detail-head .sub { color: var(--muted); margin: 4px 0 0; }
.tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin: 16px 0; }
.tile { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 11px 14px; }
.tile b { display: block; font-family: var(--mono); font-size: 18px; font-weight: 600; margin-top: 2px; }
.tile span { color: var(--faint); font-size: 11.5px; text-transform: uppercase; letter-spacing: 0.08em; }
.cols { display: grid; grid-template-columns: 1fr 1.35fr; gap: 14px; align-items: start; }
@media (max-width: 860px) { .cols { grid-template-columns: 1fr; } }
.box { padding: 16px 18px; }
.box h3 { margin: 0 0 10px; font-size: 15px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); }
.math { width: 100%; }
.math td { padding: 7px 4px; border-bottom: 1px dashed rgba(30, 47, 79, 0.8); cursor: default; }
.math tr:hover { background: none; }
.math td.n { font-size: 14.5px; }
.math tr.total td { border-bottom: none; border-top: 2px solid var(--line2); font-weight: 700; }
.math tr.total td.n { color: var(--signal); font-size: 16.5px; }
ol.plan { margin: 0; padding-left: 22px; }
ol.plan li { margin-bottom: 13px; }
ol.plan .step-text { display: block; }
.chips { display: block; margin-top: 3px; }
.chip { display: inline-block; font-family: var(--mono); font-size: 12px; color: var(--cyan); background: rgba(56, 189, 248, 0.08); border: 1px solid rgba(56, 189, 248, 0.25); border-radius: 999px; padding: 1px 8px; margin-right: 6px; }
.chip.time { color: var(--amber); background: rgba(251, 191, 36, 0.07); border-color: rgba(251, 191, 36, 0.28); }
.why { color: var(--muted); }
.why b { color: var(--ink); }

/* Model page */
.formula { font-family: var(--mono); font-size: 16.5px; background: var(--bg2); border: 1px solid var(--line2); border-radius: 10px; padding: 14px 18px; overflow-x: auto; white-space: nowrap; }
.kv { display: grid; grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); gap: 10px 26px; }
.kv div { display: flex; justify-content: space-between; border-bottom: 1px dashed rgba(30, 47, 79, 0.8); padding: 5px 0; }
.kv div span:first-child { color: var(--muted); }
.kv div span:last-child { font-family: var(--mono); }
.model-sec { margin-bottom: 14px; padding: 16px 18px; }
.model-sec h3 { margin: 0 0 8px; font-size: 15px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); }
.model-sec p { margin: 0 0 8px; color: var(--muted); max-width: 880px; }
.model-sec p b, .model-sec li b { color: var(--ink); }
.model-sec ul { margin: 0; padding-left: 20px; color: var(--muted); }
.model-sec li { margin-bottom: 5px; }

.foot { max-width: 1180px; margin: 0 auto; padding: 6px 20px 30px; color: var(--faint); font-size: 13px; }
.foot p { margin: 4px 0; }
"}

{"file_path": "dashboard/app.js", "content": "// Token Radar: the board, a detail view per protocol, the live-token set, and the model, rendered
// from window.RADAR (../data.js, written by main.ts from the same board board.json hands in).
// No framework, no fetch, no network: the page works from its files alone. The view lives in the
// hash (#/, #/live, #/model, #/p/<slug>, #/?cat=..&chain=..&q=..&watch=1&sort=..&dir=..), so a
// filtered or detail view is a link, and the back button walks the reader's own path.

const R = window.RADAR;
const app = document.getElementById('app');
const statsEl = document.getElementById('stats');

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const commas = (v) => Math.round(v).toLocaleString('en-US');
function money(v) {
  if (v === null || v === undefined) return '—';
  if (v >= 1e9) return `$${(v / 1e9).toFixed(2)}B`;
  if (v >= 1e6) return `$${(v / 1e6).toFixed(1)}M`;
  if (v >= 1e3) return `$${(v / 1e3).toFixed(1)}K`;
  return `$${commas(v)}`;
}
const pct = (v) => (v === null || v === undefined ? '—' : `${v > 0 ? '+' : ''}${Number(v).toFixed(1)}%`);
const pctClass = (v) => (v === null || v === undefined || v === 0 ? '' : v > 0 ? 'pos' : 'neg');
function ageText(days) {
  if (days === null || days === undefined) return 'unknown';
  if (days < 365) return `${days}d`;
  return `${(days / 365).toFixed(1)} yrs`;
}
const bySlug = new Map(R.rows.map((r) => [r.slug, r]));

/* ---------- header ---------- */
function renderStats() {
  const cells = [
    [R.protocols_size, 'protocols scanned'],
    [R.watchlist_size, 'watchlist covered'],
    [R.board_size, 'ranked pre-token'],
    [R.early_size, 'early finds'],
    [R.live_size, 'live tokens tracked'],
  ];
  statsEl.innerHTML = cells.map(([v, label]) => `<div class="stat"><b>${v}</b><span>${label}</span></div>`).join('');
  document.getElementById('source-line').textContent =
    `Data: ${R.source}. Snapshot date ${R.as_of}; watchlist floor ${money(R.floor_usd)} of TVL. Model ${R.model_version}, run over the sealed snapshot's own figures only.`;
}
function setTab(name) {
  for (const a of document.querySelectorAll('.tabs a')) a.classList.toggle('on', a.dataset.tab === name);
}

/* ---------- board ---------- */
const SORTS = {
  rank: { label: 'Rank', num: true },
  name: { label: 'Protocol', num: false },
  tvl: { label: 'TVL', num: true },
  change: { label: '7d', num: true },
  age: { label: 'Age', num: true },
  implied: { label: 'Implied value', num: true },
};
function sortValue(row, key) {
  if (key === 'rank') return row.rank;
  if (key === 'name') return row.name.toLowerCase();
  if (key === 'tvl') return row.tvl_usd;
  if (key === 'change') return row.change_7d;
  if (key === 'age') return row.age_days;
  return row.implied_value_usd;
}
function boardState(params) {
  return {
    q: params.get('q') ?? '',
    cat: params.get('cat') ?? '',
    chain: params.get('chain') ?? '',
    watch: params.get('watch') === '1',
    sort: SORTS[params.get('sort')] ? params.get('sort') : 'rank',
    dir: params.get('dir') === 'asc' ? 'asc' : params.get('sort') ? params.get('dir') || 'desc' : 'asc',
  };
}
function stateHash(st) {
  const p = new URLSearchParams();
  if (st.q) p.set('q', st.q);
  if (st.cat) p.set('cat', st.cat);
  if (st.chain) p.set('chain', st.chain);
  if (st.watch) p.set('watch', '1');
  if (st.sort !== 'rank') p.set('sort', st.sort);
  if (st.dir !== 'asc') p.set('dir', st.dir);
  const s = p.toString();
  return s ? `#/?${s}` : '#/';
}
function filteredRows(st) {
  const q = st.q.trim().toLowerCase();
  let rows = R.rows.filter((r) => {
    if (st.watch && !r.on_watchlist) return false;
    if (st.cat && r.category !== st.cat) return false;
    if (st.chain && !r.chains.includes(st.chain)) return false;
    if (q && !r.name.toLowerCase().includes(q) && !r.slug.includes(q)) return false;
    return true;
  });
  const mul = st.dir === 'asc' ? 1 : -1;
  rows = [...rows].sort((a, b) => {
    const va = sortValue(a, st.sort);
    const vb = sortValue(b, st.sort);
    if (va === null || va === undefined) return 1;
    if (vb === null || vb === undefined) return -1;
    if (va < vb) return -1 * mul;
    if (va > vb) return 1 * mul;
    return a.rank - b.rank;
  });
  return rows;
}
function options(values, current, allLabel) {
  return [`<option value="">${allLabel}</option>`, ...values.map((v) => `<option value="${esc(v)}"${v === current ? ' selected' : ''}>${esc(v)}</option>`)].join('');
}
function renderBoard(params) {
  setTab('board');
  const st = boardState(params);
  const cats = [...new Set(R.rows.map((r) => r.category).filter(Boolean))].sort();
  const chainCount = new Map();
  for (const r of R.rows) for (const c of r.chains) chainCount.set(c, (chainCount.get(c) ?? 0) + 1);
  const chains = [...chainCount.entries()].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1)).map(([c]) => c);
  const rows = filteredRows(st);
  const maxImplied = R.rows[0]?.implied_value_usd ?? 1;
  const head = Object.entries(SORTS)
    .map(([key, s]) => {
      const arrow = st.sort === key ? ` <span class="dir">${st.dir === 'asc' ? '▲' : '▼'}</span>` : '';
      return `<th class="sortable${s.num ? ' n' : ''}" data-sort="${key}">${s.label}${arrow}</th>`;
    })
    .join('');
  const body = rows
    .map((r) => {
      const badge = r.on_watchlist ? '<span class="badge watch">watchlist</span>' : '<span class="badge early">early</span>';
      const share = Math.max(2, Math.round((r.implied_value_usd / maxImplied) * 100));
      return `<tr data-slug="${esc(r.slug)}">
        <td class="rank">${r.rank}</td>
        <td><span class="pname">${esc(r.name)}</span>${badge}<br><span class="pcat">${esc(r.category ?? 'Uncategorised')}</span></td>
        <td class="chains">${esc(r.chains.slice(0, 3).join(', '))}${r.chains.length > 3 ? ` +${r.chains.length - 3}` : ''}</td>
        <td class="n">${money(r.tvl_usd)}</td>
        <td class="n ${pctClass(r.change_7d)}">${pct(r.change_7d)}</td>
        <td class="n">${ageText(r.age_days)}</td>
        <td class="n"><b>${money(r.implied_value_usd)}</b><span class="bar"><i style="width:${share}%"></i></span></td>
      </tr>`;
    })
    .join('');
  app.innerHTML = `
    <p class="lede">Every protocol on the snapshot's <b>watchlist</b> is here, ranked by the model's implied value — plus every
    pre-token launch candidate the radar found <b>below the ${money(R.floor_usd)} floor</b> (${R.early_size} early finds), because a launch
    worth farming rarely waits to be large. Click a row for its value math and its farm plan.</p>
    <div class="panel controls">
      <input type="search" id="f-q" placeholder="Search name or slug…" value="${esc(st.q)}" aria-label="Search">
      <select id="f-cat" aria-label="Category">${options(cats, st.cat, 'All categories')}</select>
      <select id="f-chain" aria-label="Chain">${options(chains, st.chain, 'All chains')}</select>
      <label class="check"><input type="checkbox" id="f-watch"${st.watch ? ' checked' : ''}> Watchlist only</label>
      <button class="reset" id="f-reset" type="button">Reset</button>
      <span class="count">${rows.length} of ${R.board_size} shown</span>
    </div>
    <div class="panel board-wrap"><table>
      <thead><tr>${head}</tr></thead>
      <tbody>${body || `<tr><td colspan="7" class="empty">No protocol matches that filter. Loosen it — the radar is wider than one view.</td></tr>`}</tbody>
    </table></div>`;
  app.setAttribute('aria-busy', 'false');
  const update = (patch) => {
    const next = { ...st, ...patch };
    history.replaceState(null, '', stateHash(next));
    renderBoard(new URLSearchParams(stateHash(next).split('?')[1] ?? ''));
  };
  let timer = null;
  document.getElementById('f-q').addEventListener('input', (e) => {
    clearTimeout(timer);
    timer = setTimeout(() => update({ q: e.target.value }), 160);
  });
  document.getElementById('f-cat').addEventListener('change', (e) => update({ cat: e.target.value }));
  document.getElementById('f-chain').addEventListener('change', (e) => update({ chain: e.target.value }));
  document.getElementById('f-watch').addEventListener('change', (e) => update({ watch: e.target.checked }));
  document.getElementById('f-reset').addEventListener('click', () => {
    history.replaceState(null, '', '#/');
    renderBoard(new URLSearchParams());
  });
  for (const th of app.querySelectorAll('th.sortable')) {
    th.addEventListener('click', () => {
      const key = th.dataset.sort;
      update({ sort: key, dir: st.sort === key && st.dir === 'desc' ? 'asc' : st.sort === key ? 'asc' : SORTS[key].num ? 'desc' : 'asc' });
    });
  }
  for (const tr of app.querySelectorAll('tbody tr[data-slug]')) {
    tr.addEventListener('click', () => {
      location.hash = `#/p/${tr.dataset.slug}`;
    });
  }
}

/* ---------- detail ---------- */
function splitStep(s) {
  const at = s.indexOf(' Cost: ');
  if (at < 0) return { text: s, cost: null, time: null };
  const text = s.slice(0, at);
  const rest = s.slice(at + ' Cost: '.length);
  const tAt = rest.lastIndexOf('. Time: ');
  if (tAt < 0) return { text, cost: rest.replace(/\.$/, ''), time: null };
  return { text, cost: rest.slice(0, tAt), time: rest.slice(tAt + '. Time: '.length).replace(/\.$/, '') };
}
function renderDetail(slug) {
  setTab('board');
  const r = bySlug.get(slug);
  if (!r) {
    app.innerHTML = `<p class="lede">No protocol with the slug <b>${esc(slug)}</b> is on the board.</p><p><a class="back" href="#/">← Back to the board</a></p>`;
    return;
  }
  const m = r.model;
  const base = r.tvl_usd * m.category_multiple;
  const afterGrowth = base * m.growth_multiplier;
  const afterMaturity = afterGrowth * m.maturity_multiplier;
  const reachLine =
    m.reach_multiplier !== undefined
      ? `<tr><td>× reach, ${r.chains.length} chain${r.chains.length === 1 ? '' : 's'} of distribution</td><td class="n">× ${m.reach_multiplier.toFixed(4)}</td><td class="n">${money(afterMaturity * m.reach_multiplier)}</td></tr>`
      : '';
  const prev = R.rows[r.rank - 2];
  const next = R.rows[r.rank];
  const why = [
    `<b>${esc(r.name)}</b> holds rank ${r.rank} of ${R.board_size}: ${money(r.tvl_usd)} of TVL in ${esc(r.category ?? 'its category')} at the category rate ×${m.category_multiple}`,
    `a seven-day move of ${pct(r.change_7d)} worth ×${m.growth_multiplier.toFixed(2)}, and ${r.age_days === null ? 'an unrecorded listing day, scored as a year' : `${r.age_days} days of token-free history`} worth ×${m.maturity_multiplier.toFixed(2)}`,
    prev ? `put it behind <b>${esc(prev.name)}</b> (${money(prev.implied_value_usd)})` : 'put it at the head of the board',
    next ? `and ahead of <b>${esc(next.name)}</b> (${money(next.implied_value_usd)}).` : 'with nothing below it left to pass.',
  ].join(' ');
  const plan = r.farm_steps
    .map((s) => {
      const p = splitStep(s);
      const chips = [p.cost ? `<span class="chip">Cost: ${esc(p.cost)}</span>` : '', p.time ? `<span class="chip time">Time: ${esc(p.time)}</span>` : ''].join('');
      return `<li><span class="step-text">${esc(p.text)}</span><span class="chips">${chips}</span></li>`;
    })
    .join('');
  app.innerHTML = `
    <a class="back" href="#/">← Back to the board</a>
    <div class="detail-head">
      <div>
        <h2>${esc(r.name)} ${r.on_watchlist ? '<span class="badge watch">watchlist</span>' : '<span class="badge early">early find</span>'}</h2>
        <p class="sub">${esc(r.category ?? 'Uncategorised')} · ${esc(r.chains.join(', ') || 'no chains recorded')} · records no token</p>
      </div>
      <div class="tile" style="min-width:190px"><span>Implied value</span><b style="color:var(--signal)">${money(r.implied_value_usd)}</b></div>
    </div>
    <div class="tiles">
      <div class="tile"><span>Rank</span><b>#${r.rank}</b></div>
      <div class="tile"><span>TVL</span><b>${money(r.tvl_usd)}</b></div>
      <div class="tile"><span>7-day TVL change</span><b class="${pctClass(r.change_7d)}">${pct(r.change_7d)}</b></div>
      <div class="tile"><span>Token-free age</span><b>${ageText(r.age_days)}</b></div>
      <div class="tile"><span>Tracked since</span><b>${esc(r.listed_at ?? '—')}</b></div>
      <div class="tile"><span>Farm capital</span><b>$${commas(r.farm_capital_usd)}</b></div>
    </div>
    <div class="cols">
      <section class="panel box">
        <h3>Why this value</h3>
        <table class="math"><tbody>
          <tr><td>TVL × category rate (${esc(r.category ?? 'default')} ×${m.category_multiple})</td><td class="n"></td><td class="n">${money(base)}</td></tr>
          <tr><td>× growth, seven-day TVL ${pct(m.growth_pct)}</td><td class="n">× ${m.growth_multiplier.toFixed(4)}</td><td class="n">${money(afterGrowth)}</td></tr>
          <tr><td>× maturity, ${r.age_days === null ? 'age unrecorded' : `${r.age_days} days`} with no token</td><td class="n">× ${m.maturity_multiplier.toFixed(4)}</td><td class="n">${money(afterMaturity)}</td></tr>
          ${reachLine}
          <tr class="total"><td>Implied value if it launched at this record</td><td class="n"></td><td class="n">${money(r.implied_value_usd)}</td></tr>
        </tbody></table>
        <p class="why">${why}</p>
      </section>
      <section class="panel box">
        <h3>How to farm it</h3>
        <ol class="plan">${plan}</ol>
      </section>
    </div>`;
  app.setAttribute('aria-busy', 'false');
}

/* ---------- live tokens ---------- */
function renderLive() {
  setTab('live');
  const body = R.live
    .map(
      (p, i) => `<tr data-live="${esc(p.slug)}">
        <td class="rank">${i + 1}</td>
        <td><span class="pname">${esc(p.name)}</span> <span class="pcat">${esc(p.symbol ?? '')}</span><br><span class="pcat">${esc(p.category ?? 'Uncategorised')}</span></td>
        <td class="chains">${esc(p.chains.slice(0, 3).join(', '))}${p.chains.length > 3 ? ` +${p.chains.length - 3}` : ''}</td>
        <td class="n">${money(p.tvl_usd)}</td>
        <td class="n">${money(p.mcap_usd)}</td>
        <td class="n ${pctClass(p.change_7d)}">${pct(p.change_7d)}</td>
      </tr>`,
    )
    .join('');
  app.innerHTML = `
    <p class="lede">These protocols' tokens <b>already trade</b>, so the radar does not rank them: the market has already priced them,
    and the board's implied values would only echo it. They are kept here, at the market's own figures, as the scale the pre-token
    board is measured against — and as proof of the separation: nothing with a live token takes a ranked row.</p>
    <div class="panel board-wrap"><table>
      <thead><tr><th>#</th><th>Protocol</th><th>Chains</th><th class="n">TVL</th><th class="n">Market cap</th><th class="n">7d</th></tr></thead>
      <tbody>${body}</tbody>
    </table></div>`;
  app.setAttribute('aria-busy', 'false');
}

/* ---------- the model ---------- */
function renderModel() {
  setTab('model');
  const m = R.model;
  const multiples = Object.entries(m.category_multiples)
    .sort((a, b) => b[1] - a[1])
    .map(([k, v]) => `<div><span>${esc(k)}</span><span>× ${v}</span></div>`)
    .join('');
  const reach = m.reach_per_chain !== undefined ? `<li><b>Reach:</b> +${Math.round(m.reach_per_chain * 100)}% per chain beyond the first, up to ${m.reach_max_chains} extra chains — a launch distributed on seven chains starts with seven audiences.</li>` : '';
  app.innerHTML = `
    <section class="panel model-sec">
      <h3>One formula, every row</h3>
      <p class="formula">implied value = TVL × category rate × growth × maturity${m.reach_per_chain !== undefined ? ' × reach' : ''}</p>
      <p>No protocol is named anywhere in the model. The same function scores a $5M lending market and a $2B curator,
      from the snapshot's own figures alone, so a protocol that does not exist yet is scored the day the snapshot records it.</p>
    </section>
    <section class="panel model-sec">
      <h3>The four factors</h3>
      <ul>
        <li><b>Category rate:</b> what a dollar of TVL in the category has historically been worth in token value — fee-capturing trading and lending at the top, pass-through wrappers and bridges at the bottom.</li>
        <li><b>Growth:</b> the seven-day TVL change, clamped to ${m.growth_floor}%…+${m.growth_cap}%, weighted ×${m.growth_weight}: a protocol that doubled in a week is worth 1.6× its base; one that halved, 0.7×.</li>
        <li><b>Maturity:</b> ${m.maturity_floor} + ${m.maturity_range} × age / ${m.maturity_days} days: the longer a protocol has run with no token, the more of its record a launch can be priced on. An unrecorded listing day scores as ${m.unknown_age_days} days.</li>
        ${reach}
      </ul>
    </section>
    <section class="panel model-sec">
      <h3>Category rates</h3>
      <div class="kv">${multiples}<div><span>Every other category</span><span>× ${m.default_multiple}</span></div></div>
    </section>
    <section class="panel model-sec">
      <h3>Who gets on the board</h3>
      <ul>
        <li><b>The watchlist is the floor:</b> all ${R.watchlist_size} of the snapshot's watchlist protocols (TVL at or above ${money(R.floor_usd)}, no token recorded, no wrapped or staked product) are ranked, whatever the model says.</li>
        <li><b>Early finds:</b> below the floor, every protocol that records no token and passes the watchlist rule's own product tests — no versioned pool names, no wrapped or staked products, no exchange-issued products — is ranked too: ${R.early_size} of them. The radar carries all of them rather than a sample, so it cannot miss the one that launches next.</li>
        <li><b>Live tokens are separated:</b> a protocol whose token already trades never takes a ranked row; the Live tokens view shows it at the market's own value.</li>
        <li><b>A record, not a proof:</b> "records no token" is what DefiLlama's record says. The board says exactly that, and nothing stronger.</li>
      </ul>
    </section>`;
  app.setAttribute('aria-busy', 'false');
}

/* ---------- router ---------- */
function route() {
  const hash = location.hash || '#/';
  const [path, query] = hash.slice(1).split('?');
  const params = new URLSearchParams(query ?? '');
  window.scrollTo(0, 0);
  if (path === '/live') return renderLive();
  if (path === '/model') return renderModel();
  if (path.startsWith('/p/')) return renderDetail(decodeURIComponent(path.slice(3)));
  return renderBoard(params);
}
window.addEventListener('hashchange', route);
renderStats();
route();
"}

